const entrada = $input.first().json;
const body = entrada.body ?? entrada;
const fields = body?.data?.fields ?? [];

const datos = {};
for (const f of fields) {
  let valor = f.value;

  // Si el campo es una lista de opciones, la convertimos a texto
  if (Array.isArray(valor) && Array.isArray(f.options)) {
    valor = valor
      .map(id => f.options.find(o => o.id === id)?.text ?? id)
      .join(', ');
  } else if (Array.isArray(valor)) {
    valor = valor.join(', ');
  }

  // Si viene vacío, lo marcamos como no informado
  if (valor === null || valor === undefined || valor === '') {
    valor = 'No informado';
  }

  datos[f.label] = valor;
}

return [{ json: { datos } }];;;

